    for i in range(R):
        for j in range(C):
            if g[i][j]!=bg and (i,j) not in seen:
                stack=[(i,j)]; seen.add((i,j)); cs_=[]
                while stack:
                    a,b=stack.pop(); cs_.append((a,b))
                    for da in (-1,0,1):
                        for db in (-1,0,1):
