def variants(cs_):
    res=set()
    for f in (lambda p:(p[0],p[1]),lambda p:(p[1],p[0]),lambda p:(p[0],-p[1]),lambda p:(-p[0],p[1]),
              lambda p:(-p[0],-p[1]),lambda p:(-p[1],-p[0]),lambda p:(p[1],-p[0]),lambda p:(-p[1],p[0])):
        m=f((0,1)); n=f((1,0))
        # canonical: apply linear map f to normalized coords
        cells=[(a-min(a for a,b in [(x,y) for x,y in cs_]), b-min(b for a,b in [(x,y) for x,y in cs_])) for a,b in cs_]
        mapped=[f(c) for c in cells]
        ma=min(a for a,b in mapped); mb=min(b for a,b in mapped)
        res.add(tuple(sorted((a-ma,b-mb) for a,b in mapped)))
    return res
