def group_stats(gi, bg, ref_color):
    os_ = objs2(gi, bg, 8)
    ref = [o for o in os_ if o[0]==ref_color][0]
    refc = (sum(c[0] for c in ref[1])/len(ref[1]), sum(c[1] for c in ref[1])/len(ref[1]))
    from collections import defaultdict
    shapes=defaultdict(list)
    for o in os_:
        shapes[frozenset(variants2(o[1]))].append(o)
    res=[]
    for k,v in shapes.items():
        if len(v)>1:
            def cen(o): return (sum(c[0] for c in o[1])/len(o[1]), sum(c[1] for c in o[1])/len(o[1]))
            ds=[((cen(o)[0]-refc[0])**2+(cen(o)[1]-refc[1])**2)**.5 for o in v]
            mean_d=sum(ds)/len(ds)
            far=max(v,key=lambda o:((cen(o)[0]-refc[0])**2+(cen(o)[1]-refc[1])**2))
            res.append((len(v), len(v[0][1]), round(mean_d,2), far[0], far[1][0], [ (o[0],o[1][0]) for o in v]))
    return sorted(res,key=lambda r:r[2])

